create extension if not exists btree_gist;
create type public.app_role as enum ('doctor','secretary');
create table public.clinic_settings (id uuid primary key default gen_random_uuid(), owner_id uuid not null unique, doctor_name text not null default '', clinic_name text not null default 'Mon cabinet', address text default '', phone text default '', matricule text default '', stamp_data text, signature_data text, booking_enabled boolean not null default true, updated_at timestamptz not null default now());
grant select,update on public.clinic_settings to authenticated; grant all on public.clinic_settings to service_role; alter table public.clinic_settings enable row level security;
create table public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, clinic_id uuid not null references public.clinic_settings(id), role public.app_role not null, unique(user_id));
grant select on public.user_roles to authenticated; grant all on public.user_roles to service_role; alter table public.user_roles enable row level security;
create function public.current_clinic() returns uuid language sql stable security definer set search_path=public as $$ select clinic_id from public.user_roles where user_id=auth.uid() $$;
create function public.has_role(_user_id uuid,_role public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=_user_id and role=_role) $$;
create policy own_role on public.user_roles for select to authenticated using(user_id=auth.uid());
create policy clinic_read on public.clinic_settings for select to authenticated using(id=public.current_clinic());
create policy clinic_update on public.clinic_settings for update to authenticated using(id=public.current_clinic() and public.has_role(auth.uid(),'doctor')) with check(id=public.current_clinic() and owner_id=auth.uid());
create function public.create_dental_workspace() returns trigger language plpgsql security definer set search_path=public as $$ declare c uuid; begin insert into public.clinic_settings(owner_id) values(new.id) returning id into c; insert into public.user_roles(user_id,clinic_id,role) values(new.id,c,'doctor'); return new; end $$;
create trigger create_workspace after insert on auth.users for each row execute function public.create_dental_workspace();
create table public.patients (id uuid primary key default gen_random_uuid(), clinic_id uuid not null default public.current_clinic() references public.clinic_settings(id), full_name text not null, phone text, email text, birth_date date, address text, cnam_number text, allergies text, notes text, share_token uuid not null default gen_random_uuid() unique, created_at timestamptz not null default now(), unique(id,clinic_id));
grant select,insert,update,delete on public.patients to authenticated; grant all on public.patients to service_role; alter table public.patients enable row level security;
create policy patient_access on public.patients for all to authenticated using(clinic_id=public.current_clinic()) with check(clinic_id=public.current_clinic());
create table public.appointments (id uuid primary key default gen_random_uuid(), clinic_id uuid not null default public.current_clinic() references public.clinic_settings(id), patient_id uuid not null, starts_at timestamptz not null, ends_at timestamptz not null, reason text, status text not null default 'scheduled' check(status in('scheduled','done','cancelled','no_show')), created_at timestamptz not null default now(), foreign key(patient_id,clinic_id) references public.patients(id,clinic_id) on delete cascade, check(ends_at>starts_at), exclude using gist(clinic_id with =,tstzrange(starts_at,ends_at,'[)') with &&) where(status in('scheduled','done')));
grant select,insert,update,delete on public.appointments to authenticated; grant all on public.appointments to service_role; alter table public.appointments enable row level security;
create policy appointment_access on public.appointments for all to authenticated using(clinic_id=public.current_clinic()) with check(clinic_id=public.current_clinic());
create table public.visits (id uuid primary key default gen_random_uuid(), clinic_id uuid not null default public.current_clinic() references public.clinic_settings(id), patient_id uuid not null, visit_date date not null default current_date, treatment text not null, tooth text, details text, medications text, cost numeric(10,3) not null default 0 check(cost>=0), amount_paid numeric(10,3) not null default 0 check(amount_paid>=0 and amount_paid<=cost), cnam_eligible boolean not null default true, created_at timestamptz not null default now(), foreign key(patient_id,clinic_id) references public.patients(id,clinic_id) on delete cascade);
grant select,insert,update,delete on public.visits to authenticated; grant all on public.visits to service_role; alter table public.visits enable row level security;
create policy visit_access on public.visits for all to authenticated using(clinic_id=public.current_clinic()) with check(clinic_id=public.current_clinic());
create table public.treatment_plans (id uuid primary key default gen_random_uuid(), clinic_id uuid not null default public.current_clinic() references public.clinic_settings(id), patient_id uuid not null, treatment_type text not null, details text, status text not null default 'planned' check(status in('planned','done')), created_at timestamptz not null default now(), foreign key(patient_id,clinic_id) references public.patients(id,clinic_id) on delete cascade);
grant select,insert,update,delete on public.treatment_plans to authenticated; grant all on public.treatment_plans to service_role; alter table public.treatment_plans enable row level security;
create policy plan_read on public.treatment_plans for select to authenticated using(clinic_id=public.current_clinic()); create policy plan_write on public.treatment_plans for all to authenticated using(clinic_id=public.current_clinic() and public.has_role(auth.uid(),'doctor')) with check(clinic_id=public.current_clinic() and public.has_role(auth.uid(),'doctor'));
create table public.prescriptions (id uuid primary key default gen_random_uuid(), clinic_id uuid not null default public.current_clinic() references public.clinic_settings(id), patient_id uuid not null, items jsonb not null default '[]', notes text, created_at timestamptz not null default now(), foreign key(patient_id,clinic_id) references public.patients(id,clinic_id) on delete cascade);
grant select,insert,update,delete on public.prescriptions to authenticated; grant all on public.prescriptions to service_role; alter table public.prescriptions enable row level security;
create policy prescription_access on public.prescriptions for all to authenticated using(clinic_id=public.current_clinic()) with check(clinic_id=public.current_clinic());
create table public.booking_requests (id uuid primary key default gen_random_uuid(), clinic_id uuid not null default public.current_clinic() references public.clinic_settings(id), full_name text not null check(char_length(full_name) between 2 and 100), phone text not null check(char_length(phone) between 6 and 20), preferred text check(char_length(preferred)<=200), status text not null default 'pending' check(status in('pending','confirmed','dismissed')), created_at timestamptz not null default now());
grant select,insert,update,delete on public.booking_requests to authenticated; grant insert on public.booking_requests to anon; grant all on public.booking_requests to service_role; alter table public.booking_requests enable row level security;
create function public.clinic_accepts_booking(c uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.clinic_settings where id=c and booking_enabled)$$;
create policy request_access on public.booking_requests for all to authenticated using(clinic_id=public.current_clinic()) with check(clinic_id=public.current_clinic()); create policy public_booking on public.booking_requests for insert to anon,authenticated with check(status='pending' and public.clinic_accepts_booking(clinic_id));
create table public.inventory_items (id uuid primary key default gen_random_uuid(), clinic_id uuid not null default public.current_clinic() references public.clinic_settings(id), name text not null, unit text default 'unité', quantity numeric not null default 0 check(quantity>=0), min_quantity numeric not null default 5 check(min_quantity>=0), created_at timestamptz not null default now());
grant select,insert,update,delete on public.inventory_items to authenticated; grant all on public.inventory_items to service_role; alter table public.inventory_items enable row level security;
create policy inventory_access on public.inventory_items for all to authenticated using(clinic_id=public.current_clinic()) with check(clinic_id=public.current_clinic());
create table public.expenses (id uuid primary key default gen_random_uuid(), clinic_id uuid not null default public.current_clinic() references public.clinic_settings(id), label text not null, amount numeric(10,3) not null check(amount>=0), expense_date date not null default current_date, created_at timestamptz not null default now());
grant select,insert,update,delete on public.expenses to authenticated; grant all on public.expenses to service_role; alter table public.expenses enable row level security;
create policy expense_access on public.expenses for all to authenticated using(clinic_id=public.current_clinic() and public.has_role(auth.uid(),'doctor')) with check(clinic_id=public.current_clinic() and public.has_role(auth.uid(),'doctor'));
create function public.public_clinic(c uuid) returns table(id uuid,clinic_name text,doctor_name text,address text,phone text) language sql stable security definer set search_path=public as $$select id,clinic_name,doctor_name,address,phone from public.clinic_settings where id=c and booking_enabled$$; grant execute on function public.public_clinic(uuid) to anon,authenticated;
create index patients_clinic_name on public.patients(clinic_id,full_name); create index appointments_clinic_time on public.appointments(clinic_id,starts_at);